const fileName = $input.item.json.name;
const baseName = fileName.split('.')[0].toLowerCase().replace(/[^a-z0-9]/g, '-');
const timestamp = new Date().getTime();
const bucketName = `n8n-batch-${baseName}-${timestamp}`;
const folderName = fileName.split('.')[0];

return {
  project_label: baseName,
  gdrive_audio_folder: folderName,
  bucket_name: bucketName,
  gcs_audio_path: `gs://${bucketName}/audio/`,
  gcs_batch_path: `gs://${bucketName}/batch/`,
  gcs_results_path: `gs://${bucketName}/results/`,
  is_test: fileName.toLowerCase().includes('test')
};

parameters.command:
=cd /opt/n8n_data/datasets/{{ $('Init Variables/Ініціалізація змінних').first().json.project_label }} && \
mkdir -p temp_chunks && \
rm -rf temp_chunks/* && \
gcloud auth activate-service-account --key-file=/opt/n8n_data/gcp-key.json && \
python3 -c "
import pandas as pd, json, os, sys, subprocess

try:
    bucket = '{{ $('Init Variables/Ініціалізація змінних').first().json.bucket_name }}'
    print('Сканирую бакет...')
    result = subprocess.run(['gsutil', 'ls', f'gs://{bucket}/**.wav'], capture_output=True, text=True)
    real_paths = result.stdout.strip().split('\n')

    time_map = {}
    for p in real_paths:
        if '___' in p:
            time_map[p.split('___')[-1]] = p

    df = pd.read_csv('input_dataset.csv')

    chunk_size = 5000
    total_matched = 0
    file_count = 0

    for i in range(0, len(df), chunk_size):
        chunk = df.iloc[i:i+chunk_size]
        filename = f'temp_chunks/part_{i//chunk_size}.jsonl'
        matched_in_chunk = 0

        with open(filename, 'w') as f:
            for _, row in chunk.iterrows():
                csv_path = str(row['file'])
                if '___' in csv_path:
                    csv_time = csv_path.split('___')[-1].strip()
                    if csv_time in time_map:
                        file_uri = time_map[csv_time]

                        # Жорсткий промпт для нейромережі
                        prompt_text = f\"REFERENCE TEXT: '{row['transcript']}'\\nTranscribe the audio exactly. Compare your transcription to the REFERENCE TEXT. If they match completely (ignoring punctuation), your verdict is 'OK'. If the REFERENCE TEXT has typos, wrong words, or missing words, your verdict is 'BRAK'. Output strictly in this format: VERDICT | YOUR_TRANSCRIPTION. Do not add any explanations.\"

                        task = {
                            'request': {
                                'contents': [{
                                    'role': 'user',
                                    'parts': [
                                        {'text': prompt_text},
                                        {'fileData': {'mimeType': 'audio/wav', 'fileUri': file_uri}}
                                    ]
                                }]
                            }
                        }
                        f.write(json.dumps(task) + '\n')
                        matched_in_chunk += 1
                        total_matched += 1

        if matched_in_chunk > 0:
            file_count += 1
        else:
            os.remove(filename)

    print(f'✅ SUCCESS: Создано {file_count} файлов. Всего найдено {total_matched} аудиозаписей!')
except Exception as e:
    print(f'ERROR: {e}'); sys.exit(1)
" && \
gsutil -m cp temp_chunks/*.jsonl gs://{{ $('Init Variables/Ініціалізація змінних').first().json.bucket_name }}/batch/

