// Берем stdout из предыдущего узла (список файлов текстом)
const stdout = $('List Batch Files/Сканування списку файлів').item.json.stdout;

// Разбиваем строку на массив по переносу строки и убираем пустые элементы
const files = stdout.split('\n').filter(f => f.trim() !== '');

// Возвращаем каждый файл как отдельный айтем для Loop
return files.map(fileName => {
  return { json: { file_name: fileName } };
});

